// HarnessServiceServer is the server API for HarnessService service.
// All implementations must embed UnimplementedHarnessServiceServer
// for forward compatibility.
//
// HarnessService is the mecatl API: unary session setup/inspection plus
// the bidi Converse stream that drives one agent run.
type HarnessServiceServer interface {
	// GetCompatibilityInfo returns the deployment's compatibility descriptor: the
	// API major, the operator-enabled ServerCapabilities, the build's supported
	// feature identifiers, and an optional operator-set deployment label. It is
	// the FIRST call a client makes — it answers "what may I do with this
	// server?" WITHOUT creating a probe session (the ServerCapabilities echo
	// otherwise rides CreateSessionResponse only).
	//
	// DISTINCT FROM GetServerInfo below, deliberately. That RPC answers "which
	// BUILD is this?" and ADR 0245 draws an explicit privacy boundary around it:
	// its response must never carry capabilities, configuration, or auth details.
	// This one is exactly those things — negotiation input, not identity — so
	// folding the two would either breach that boundary or overload one message
	// with two audiences. Build identity therefore lives ONLY on GetServerInfo,
	// and a client that wants both makes both calls.
	//
	// A server that does not implement this RPC (UNIMPLEMENTED) is below the
	// SDK compatibility floor; a client fails loudly rather than inferring a
	// legacy mode. Authenticated like every other RPC, so UNAUTHENTICATED and
	// UNIMPLEMENTED stay distinguishable. See ADR 0248.
	GetCompatibilityInfo(context.Context, *GetCompatibilityInfoRequest) (*GetCompatibilityInfoResponse, error)
	// CreateSession allocates a new server-side session and returns its id.
	CreateSession(context.Context, *CreateSessionRequest) (*CreateSessionResponse, error)
	// GetServerInfo returns only the composed server build identity. It is authenticated
	// like every HarnessService operation and does not inspect configuration or state.
	GetServerInfo(context.Context, *GetServerInfoRequest) (*GetServerInfoResponse, error)
	// GetSession returns a snapshot of an existing session.
	GetSession(context.Context, *GetSessionRequest) (*GetSessionResponse, error)
	// GetSessionTranscript returns the authoritative, snapshot-derived human
	// transcript for one owned session. It is read-only and does not use EventLog.
	GetSessionTranscript(context.Context, *GetSessionTranscriptRequest) (*GetSessionTranscriptResponse, error)
	// SetMode changes an existing session's permission posture. The session aggregate
	// remains authoritative: a mid-turn change is rejected with InvalidArgument, so
	// clients that want "next prompt" semantics must defer and retry once idle.
	SetMode(context.Context, *SetModeRequest) (*SetModeResponse, error)
	// CloseSession ends a session and releases its server-side resources (learned
	// permission rules, bound placement, and any per-session engine). Idempotent:
	// closing an unknown or already-closed session via the wire returns NotFound only
	// for a never-created id; an already-released session succeeds.
	CloseSession(context.Context, *CloseSessionRequest) (*CloseSessionResponse, error)
	// RenameSession explicitly replaces an idle main session's title.
	RenameSession(context.Context, *RenameSessionRequest) (*RenameSessionResponse, error)
	// DeleteSession physically removes an idle main session and its sidecars.
	DeleteSession(context.Context, *DeleteSessionRequest) (*DeleteSessionResponse, error)
	// CompactSession applies one manual compaction pass to an owned main-chat
	// session at a turn boundary. It creates no model turn.
	CompactSession(context.Context, *CompactSessionRequest) (*CompactSessionResponse, error)
	// ClearSession creates a distinct empty-history successor that inherits the
	// source session's placement unless a fresh source-scoped selector is supplied.
	ClearSession(context.Context, *ClearSessionRequest) (*ClearSessionResponse, error)
	// ForkSession creates a history-carrying successor with optional placement and
	// model-routing overrides.
	ForkSession(context.Context, *ForkSessionRequest) (*ForkSessionResponse, error)
	// Converse drives one run. The first frame MUST be `prompt` or `retry`; later
	// frames may carry controls. A received second `prompt` or `retry` is rejected
	// with INVALID_ARGUMENT. The server streams `Event` envelopes until the terminal
	// `result` event, then closes the stream; controls still in transit may instead
	// observe normal stream completion. A context cancel from the client aborts the run.
	Converse(grpc.BidiStreamingServer[ConverseRequest, ConverseResponse]) error
	// ListMcpResources returns the static resource snapshots advertised by the
	// connected MCP servers. An empty `server` returns the union across every
	// server; a specific name returns just that server's. Catalog-level
	// inspection: unrelated to any in-flight Converse run.
	ListMcpResources(context.Context, *ListMcpResourcesRequest) (*ListMcpResourcesResponse, error)
	// ReadMcpResource reads a single resource by URI from the named server.
	ReadMcpResource(context.Context, *ReadMcpResourceRequest) (*ReadMcpResourceResponse, error)
	// ListMcpPrompts returns the static prompt snapshots advertised by the
	// connected MCP servers. An empty `server` returns the union across every
	// server.
	ListMcpPrompts(context.Context, *ListMcpPromptsRequest) (*ListMcpPromptsResponse, error)
	// GetMcpPrompt expands a named prompt with the given arguments on the named
	// server and returns the rendered messages.
	GetMcpPrompt(context.Context, *GetMcpPromptRequest) (*GetMcpPromptResponse, error)
	// ListMcpSources returns the cached published/pre-shadow source inventory and
	// reconciler status. It performs no independent upstream probe.
	ListMcpSources(context.Context, *ListMcpSourcesRequest) (*ListMcpSourcesResponse, error)
	// RefreshMcpSources explicitly reconciles direct MCP sources for an owned
	// eligible ordinary-root session and unions newly active direct names.
	RefreshMcpSources(context.Context, *RefreshMcpSourcesRequest) (*RefreshMcpSourcesResponse, error)
	// ListSessionMcpConnectors inspects the owned session's broker-local catalogue.
	// This read neither probes upstreams nor progresses enrollment.
	ListSessionMcpConnectors(context.Context, *ListSessionMcpConnectorsRequest) (*ListSessionMcpConnectorsResponse, error)
	// ListToolHiveGroups returns the distinct, non-empty ToolHive groups present
	// in the resolved source inventory. Derived from the snapshot — it does NOT
	// call ToolHive.
	ListToolHiveGroups(context.Context, *ListToolHiveGroupsRequest) (*ListToolHiveGroupsResponse, error)
	// ListAgents returns the resolved agent-definition registry snapshot: each
	// discovered agent def's routing metadata (name/description), its resolved
	// model, its effective read-only tool scope, permission mode, and UX color.
	// Derived from the snapshot taken at startup; it performs no live discovery.
	ListAgents(context.Context, *ListAgentsRequest) (*ListAgentsResponse, error)
	// ListCommands returns slash commands discovered for one owned session's exact
	// server-bound placement. It authorizes and reattaches that session before
	// discovery and accepts no workspace/root input. It powers the client's command
	// palette; command expansion remains a run-path concern. A no-FS session or a
	// server with no command expander returns an empty list.
	ListCommands(context.Context, *ListCommandsRequest) (*ListCommandsResponse, error)
	// ListWorktrees discovers eligible alternatives for one owned source session's
	// exactly reattached placement. Results carry bounded display metadata and an
	// opaque source-scoped selector accepted only by ClearSession or ForkSession.
	// The server re-enumerates and matches current choices on use; selectors are not
	// paths, are not persisted, and expire on restart. A no-FS session or a server
	// with no worktree lister returns an empty list.
	ListWorktrees(context.Context, *ListWorktreesRequest) (*ListWorktreesResponse, error)
	// StreamSessionEvents replays a session's durable event log as a server stream
	// of `Event` envelopes (cloud-native Phase 3a read-back). It is the client-tier
	// surface over the SAME `port.EventLog.Read` the operator-tier 3c
	// EventLogService.Read serves; the loop itself stays storage-agnostic (it only
	// emits — persistence lives at the relay, never in `engine/agent`). The log
	// stores ALREADY-REDACTED events and inherits the stream's redaction, so this
	// path adds none (gauntlet #7: no raw args/deny-reason bodies/child content
	// ever cross).
	//
	// UNLIKE the live `Converse` relay — which SKIPS the three log-only event kinds
	// (`approval`/`compaction_archive`/`user_prompt`) on the client wire because they
	// are persistence-only — StreamSessionEvents relays ALL events, including those
	// three: a client opening a PAST session wants the verdicts and user prompts, as
	// they ARE the transcript. They are metadata-only/redacted by construction, so no
	// extra filter applies here.
	//
	// Read-only: no live model call, no mutation, no Converse run is started. An
	// unknown session id yields an EMPTY stream (absence is data — a never-created or
	// pruned id is indistinguishable, by design). A server with NO durable EventLog
	// wired returns `UNIMPLEMENTED` (HTTP 501). There is intentionally NO
	// ServerCapabilities bit for this feature: the capability is RPC-discoverable
	// (UNIMPLEMENTED vs. an empty stream degrade honestly).
	StreamSessionEvents(*StreamSessionEventsRequest, grpc.ServerStreamingServer[Event]) error
	// StreamSessionLive is the LIVE per-session event stream (ADR 0075
	// fire-result-delivery Scenario 6 / Wave 3): a server-streaming RPC backed by
	// the in-process per-session subscription registry (Service.Subscribe /
	// PublishSessionEvent, List 1 row 35). It is the UNIFIED transport for BOTH
	// embedded and remote clients — the embedded mecatui dials its in-process
	// server over a real gRPC UNIX socket, so the in-process Subscribe registry is
	// unreachable from the TUI without a wire transport; this RPC is that
	// transport, and it serves a remote mecated identically (ONE proto, ONE TUI
	// consumption path).
	//
	// UNLIKE StreamSessionEvents (the durable-log READ-BACK, which relays ALL
	// events including the three log-only kinds), StreamSessionLive is a LIVE
	// stream and applies the SAME live-wire relay discipline as the live
	// `Converse` relay, with ONE narrow exception: a fire-result delivery note
	// (an EvUserPrompt whose text starts with the renderFireDelivery provenance
	// header "[scheduled task ") is RELAYED so the connected client renders the
	// delivery card as it happens (AC6.2). The other two log-only kinds
	// (EvApproval, EvCompactionArchive) stay SKIPPED on the live wire (they are
	// persistence-only; a client holds its own verdict/compaction view); a
	// non-delivery EvUserPrompt stays SKIPPED too (the client already holds its
	// own prompt). The delivery note is metadata-only/redacted by construction
	// (gauntlet #7 — it is the fenced-untrusted harness note the engine recorded).
	//
	// The stream stays open until the client cancels or disconnects. The handler
	// is drain-to-discard: a dead client never wedges the delivery run (a full
	// subscriber channel drops the event, AC6.3). The durable log records the
	// tail regardless (it is appended by the relay/loop, independent of this
	// stream). There is intentionally NO ServerCapabilities bit — the capability is
	// RPC-discoverable (UNIMPLEMENTED on an older server, an empty stream on a
	// server with no subscribers). An unknown session id yields an empty stream
	// (absence is data — a never-created id is indistinguishable from a session
	// with no live events yet).
	StreamSessionLive(*StreamSessionLiveRequest, grpc.ServerStreamingServer[Event]) error
	// WatchSessionEvents is the DURABLE replay-then-follow stream: one operation
	// that replays a session's durable event log from a position, transitions to
	// live, and keeps following as the run appends (issue #821, ADR 0250).
	//
	// It exists because neither existing read path can do this. StreamSessionEvents
	// is a complete, ordered replay with NO position and NO follow — it reads the
	// whole log and stops, so a client that wants to catch up and then watch must
	// read everything and THEN subscribe, and any event appended between those two
	// steps is silently lost. StreamSessionLive is live but process-local,
	// in-memory, and non-durable: a second replica sees nothing, a reconnecting tab
	// sees nothing that happened while it was away, and a slow subscriber has its
	// events DROPPED. Both remain, unchanged, for the callers that want exactly
	// their semantics.
	//
	// CURSOR. `cursor` is an OPAQUE resume token meaning "I have durably received
	// everything up to here". Treat it as bytes to hand back — never parse, build,
	// or edit one. An EMPTY cursor means THE BEGINNING OF THE LOG, which is a real
	// value and the common case (a client attaching for the first time wants
	// replay-then-follow). A cursor from a superseded log generation returns
	// `cursor_expired` (the log was deleted and recreated); one that cannot be
	// decoded returns `cursor_malformed`. Neither is ever coerced to a position:
	// resuming from approximately the right place is indistinguishable from
	// resuming from the right place until data is already lost.
	//
	// PHASE is an OPEN STRING, not an enum — `replay`, `live`, `gap` today, and a
	// client must tolerate a value it does not know (the same discipline the event
	// `type`/`stop` fields already carry). `replay` records were already durable
	// when the watch attached; `live` records arrived after it caught up. Exactly
	// one PHASE-ONLY `live` frame (no `event`, cursor set) marks the replay to live
	// boundary, so a client can render the transcript and then show a live view
	// WITHOUT waiting for the next event to arrive — on an idle session that event
	// may never come. `gap` marks a position where a durable append is KNOWN to
	// have failed; it too carries no `event`, because a gap is a fact about
	// DELIVERY rather than something that happened in the run (ADR 0250 decision
	// 5 — this is why neither `session.Event` nor the `Event` message gains a gap
	// field).
	//
	// RELAY DISCIPLINE mirrors StreamSessionEvents, NOT the live wire: this is the
	// READ-BACK of the durable log, so it relays ALL events including the three
	// log-only kinds (`approval`/`compaction_archive`/`user_prompt`) — a client
	// replaying a session wants the verdicts and prompts, as they ARE the
	// transcript. They are metadata-only/redacted by construction.
	//
	// `run_id` optionally narrows delivery to ONE run (ADR 0249). Gap frames are
	// delivered regardless of the filter: a failed append leaves nothing to
	// attribute to a run, so suppressing it would hide a real gap.
	//
	// TERMINATION. A watch ends when the client cancels, or with an error that says
	// what to do next. A client that falls too far behind is TERMINATED with
	// `watch_lagging` rather than having its events dropped — the cursor exists
	// precisely so that termination is recoverable: reconnect with the last cursor
	// received and nothing is lost. A durable append failure terminates the
	// watchers in that process with `activity_gap` and never advances their cursor.
	// In BOTH cases the run continues normally: a broken or slow watch must never
	// break a live run, and a watcher never backpressures one.
	//
	// A server with no durable EventLog returns `no_event_log`; one whose log does
	// not implement the cursor seam returns `watch_unsupported` — never a silent
	// degrade to replaying the whole transcript, because a client asking to resume
	// from a position and being handed everything is a correctness problem dressed
	// as a performance one. Ownership is enforced exactly as on GetSession.
	WatchSessionEvents(*WatchSessionEventsRequest, grpc.ServerStreamingServer[WatchSessionEventsResponse]) error
	// GetMcpAuthorizationPresentation returns the live browser URL for one owned,
	// still-pending authorization. The request carries correlation only; the URL
	// is returned only by this live control and never enters an Event or snapshot.
	GetMcpAuthorizationPresentation(context.Context, *GetMcpAuthorizationPresentationRequest) (*GetMcpAuthorizationPresentationResponse, error)
	// RecheckMcpAuthorization is a bidirectional authorization-control stream.
	// Its first frame MUST carry owned session/authorization correlation;
	// subsequent frames may resolve permission asks or cancel the continuation.
	RecheckMcpAuthorization(grpc.BidiStreamingServer[RecheckMcpAuthorizationRequest, RecheckMcpAuthorizationResponse]) error
	// CancelMcpAuthorization is the cancellation counterpart with the same
	// first-frame and continuation-control grammar.
	CancelMcpAuthorization(grpc.BidiStreamingServer[CancelMcpAuthorizationRequest, CancelMcpAuthorizationResponse]) error
	// ListSessions returns the stored-session inventory — the picker metadata a
	// client renders to let an operator open an EXISTING session by id (issue #245
	// Phase 1). It is backed by `port.PrunableStore.List` (type-asserted on the
	// configured store); a store that does not implement `PrunableStore`, or one that
	// returns `ErrPruneUnsupported`, degrades to an EMPTY list — never an error — so
	// a no-persistence/cloud server honestly reports "no sessions". Each row carries
	// only picker metadata (id, timestamps, state, turn count, model id); NO
	// conversation content is loaded. Rows are sorted most-recently-active first
	// (modified_at descending). Read-only. There is intentionally NO
	// ServerCapabilities bit — see StreamSessionEvents for the rationale.
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	// GetStorageHealth returns authenticated, content-free aggregate storage
	// status. It never returns session ids, owners, paths, or transcript content.
	GetStorageHealth(context.Context, *GetStorageHealthRequest) (*GetStorageHealthResponse, error)
	// Session migration is authenticated, semantics-preserving physical
	// maintenance. Plan is read-only; apply/resume process bounded batches.
	PlanSessionMigration(context.Context, *PlanSessionMigrationRequest) (*SessionMigrationPlan, error)
	ApplySessionMigration(context.Context, *ApplySessionMigrationRequest) (*SessionMigrationJob, error)
	ResumeSessionMigration(context.Context, *ResumeSessionMigrationRequest) (*SessionMigrationJob, error)
	CancelSessionMigration(context.Context, *CancelSessionMigrationRequest) (*SessionMigrationJob, error)
	GetSessionMigrationJob(context.Context, *GetSessionMigrationJobRequest) (*SessionMigrationJob, error)
	// Session cleanup is an authenticated plan/apply maintenance workflow. Plan is
	// read-only; apply requires its caller-bound opaque confirmation token.
	PlanSessionCleanup(context.Context, *PlanSessionCleanupRequest) (*PlanSessionCleanupResponse, error)
	ApplySessionCleanup(context.Context, *ApplySessionCleanupRequest) (*CleanupJob, error)
	CancelSessionCleanup(context.Context, *CancelSessionCleanupRequest) (*CleanupJob, error)
	GetSessionCleanupJob(context.Context, *GetSessionCleanupJobRequest) (*CleanupJob, error)
	// ListSkills returns the resolved skills inventory snapshot: each discovered
	// skill's name + one-line description. Derived from the snapshot taken at
	// startup (skills are discovered once at build time and immutable for the
	// process lifetime); it performs no live discovery. Metadata only — activating
	// a skill remains a run-path concern (the Skill tool reads the body).
	ListSkills(context.Context, *ListSkillsRequest) (*ListSkillsResponse, error)
	// GetSoul returns the resolved soul (user-scoped persona) BUILD-TIME SNAPSHOT:
	// the selected soul's content + size/hash + provenance (user/project) + trust
	// and drift state. The soul is selected once at startup (USER-wins precedence,
	// project trust gate, drift check — issue #14 Phase 3 Items 1+2), so this is a
	// pure read of that snapshot, never a live re-read. Read-only inspection: it
	// never mutates the soul (the agent-read-only invariant).
	GetSoul(context.Context, *GetSoulRequest) (*GetSoulResponse, error)
	// GetUserModel returns the CURRENT user-model entries (durable FACTS about the
	// operator): each entry's key + one-line description, plus an aggregate size +
	// hash. Unlike GetSoul (a startup snapshot) this is a LIVE read of the
	// user-model store's index, so it reflects entries the agent has saved since
	// startup. Metadata only — the per-entry values are omitted (Recall loads them).
	GetUserModel(context.Context, *GetUserModelRequest) (*GetUserModelResponse, error)
	// ReflectSession explicitly reflects one completed, caller-owned session. It
	// remains available when automatic learning is off if reflection is configured.
	ReflectSession(context.Context, *ReflectSessionRequest) (*ReflectSessionResponse, error)
	// Learning attempts expose content-free lifecycle metadata from only the
	// verified caller's private partition. Pagination cursors are opaque IDs.
	GetLearningAttempt(context.Context, *GetLearningAttemptRequest) (*GetLearningAttemptResponse, error)
	ListLearningAttempts(context.Context, *ListLearningAttemptsRequest) (*ListLearningAttemptsResponse, error)
	// Retry and abandon are opaque-version CAS controls over only the attempt.
	// Abandon is non-compensating and does not promise downstream rollback.
	RetryLearningAttempt(context.Context, *MutateLearningAttemptRequest) (*MutateLearningAttemptResponse, error)
	AbandonLearningAttempt(context.Context, *MutateLearningAttemptRequest) (*MutateLearningAttemptResponse, error)
	// GenerateDreamPlan creates a bounded-lifetime manual consolidation review for
	// one closed, deployment-owned target. The request carries no mutation material.
	// Unavailable deployments return Unimplemented (HTTP parity: 501).
	GenerateDreamPlan(context.Context, *GenerateDreamPlanRequest) (*GenerateDreamPlanResponse, error)
	// DecideDreamPlan applies or dismisses the exact retained plan identified by
	// plan_id. The caller cannot replace any operation or memory content.
	DecideDreamPlan(context.Context, *DecideDreamPlanRequest) (*DecideDreamPlanResponse, error)
	// ListLearningProposals returns a bounded, caller/project-partitioned page.
	ListLearningProposals(context.Context, *ListLearningProposalsRequest) (*ListLearningProposalsResponse, error)
	// GetLearningProposal returns one proposal with digest-verified evidence status.
	GetLearningProposal(context.Context, *GetLearningProposalRequest) (*GetLearningProposalResponse, error)
	// DecideLearningProposal approves or rejects a staged proposal using CAS.
	DecideLearningProposal(context.Context, *DecideLearningProposalRequest) (*DecideLearningProposalResponse, error)
	// UndoLearningPromotion commits a compensating revision only while the promoted
	// revision is still current, also guarded by proposal-version CAS.
	UndoLearningPromotion(context.Context, *UndoLearningPromotionRequest) (*UndoLearningPromotionResponse, error)
	// Learned-skill lifecycle inspection and CAS mutations. These methods are
	// caller/project partitioned and are unimplemented when no lifecycle store exists.
	ListLearnedSkills(context.Context, *ListLearnedSkillsRequest) (*ListLearnedSkillsResponse, error)
	GetLearnedSkill(context.Context, *GetLearnedSkillRequest) (*GetLearnedSkillResponse, error)
	DiffLearnedSkillVersions(context.Context, *DiffLearnedSkillVersionsRequest) (*DiffLearnedSkillVersionsResponse, error)
	ActivateLearnedSkill(context.Context, *MutateLearnedSkillRequest) (*MutateLearnedSkillResponse, error)
	RejectLearnedSkill(context.Context, *MutateLearnedSkillRequest) (*MutateLearnedSkillResponse, error)
	ArchiveLearnedSkill(context.Context, *MutateLearnedSkillRequest) (*MutateLearnedSkillResponse, error)
	RollbackLearnedSkill(context.Context, *RollbackLearnedSkillRequest) (*MutateLearnedSkillResponse, error)
	ListSkillChanges(context.Context, *ListSkillChangesRequest) (*ListSkillChangesResponse, error)
	// ListModels returns the selectable-model inventory: every AVAILABLE provider's
	// catalog models, projected to public metadata only (no secrets). It powers the
	// client /models picker (multi-provider Phase 0, S3). Derived from the build-time
	// registry+catalog snapshot; it performs no live discovery and never reveals an
	// unavailable provider.
	ListModels(context.Context, *ListModelsRequest) (*ListModelsResponse, error)
	// CreateTeam allocates a new agent team and returns its id, optionally enrolling
	// an initial roster in the same atomic call. Members may also be added afterwards
	// with SpawnTeammate; the team is then driven with RunTeam.
	CreateTeam(context.Context, *CreateTeamRequest) (*CreateTeamResponse, error)
	// SpawnTeammate enrols a member in an existing team (before RunTeam). A
	// read-only member shares the base workspace; a mutating member runs in an
	// isolated fork so parallel writes are safe.
	SpawnTeammate(context.Context, *SpawnTeammateRequest) (*SpawnTeammateResponse, error)
	// SendTeammateMessage posts a message into a member's inbox (e.g. from the
	// operator), delivered at that member's next turn boundary.
	SendTeammateMessage(context.Context, *SendTeammateMessageRequest) (*SendTeammateMessageResponse, error)
	// CancelTeammate cancels ONE member of a RUNNING team mid-round (the headless
	// RunTeam-path analogue of the Converse-path CancelChild frame). The member
	// de-schedules with the cancelled stop reason, its claimed tasks release back
	// to pending, and the team run continues — the lead still synthesises and the
	// RunTeam stream still delivers its terminal outcome frame. A team that is not
	// running (created but never run, or already done) is rejected with
	// FailedPrecondition; an unknown member name with NotFound.
	CancelTeammate(context.Context, *CancelTeammateRequest) (*CancelTeammateResponse, error)
	// RunTeam drives the team to quiescence, streaming every member's events —
	// each tagged with the member name — until the team finishes. The stream ends
	// with a single terminal frame carrying TeamEvent.outcome (rounds, stop,
	// budget_exhausted, usage, dispositions, findings); no member events follow it.
	RunTeam(*RunTeamRequest, grpc.ServerStreamingServer[TeamEvent]) error
	// ListTeam returns a snapshot of the team roster, the shared task list, and
	// whether the team has reached quiescence.
	ListTeam(context.Context, *ListTeamRequest) (*ListTeamResponse, error)
	// CleanupTeam tears down a finished team and releases its resources.
	CleanupTeam(context.Context, *CleanupTeamRequest) (*CleanupTeamResponse, error)
	// ApprovePlan atomically resolves a parked plan-approval ask (a PresentPlan
	// call surfaced in plan mode, issue #206) and — on an ALLOW verdict — starts a
	// fresh continuation run carrying the harness proceed message, streaming BOTH
	// the resumed run's and the continuation run's events on the one response
	// stream. It composes EXISTING seams (Service.resumeFromAwaiting +
	// StartRunContent over the engine's ResumeApproval): the resumed run applies
	// the verdict, sets the plan-approved target mode, terminates with
	// StopPlanApproved, and flips the session mode at the terminal boundary; the
	// continuation run then drives the model on the FLIPPED mode (default /
	// accept-edits) with the proceed message as ordinary recorded history.
	//
	// target_mode → verdict mapping:
	//   - PERMISSION_MODE_DEFAULT  → allow-once (the session flips to DEFAULT).
	//   - PERMISSION_MODE_ACCEPT_EDITS → allow-always (the session flips to
	//     ACCEPT_EDITS).
	//   - PERMISSION_MODE_PLAN / UNSPECIFIED → deny (the run stays in plan mode;
	//     no continuation run starts — the model iterates on the plan on the next
	//     prompt).
	//
	// `note` is an OPTIONAL operator remark appended to the proceed message
	// injected into the continuation run's first user message (allow paths only).
	//
	// Preconditions (else FailedPrecondition): the session must NOT have a live
	// in-flight run (an approve mid-run is rejected — use the Converse
	// ResumeApproval frame for a live run), and it MUST be in the awaiting state
	// parked on a PLAN-ORIGINATED ask (not a generic tool-permission ask). An
	// unknown session yields NotFound. The stream ends with the terminal `result`
	// event of whichever run ran last (the continuation run on an allow path; the
	// resumed run on a deny path).
	ApprovePlan(*ApprovePlanRequest, grpc.ServerStreamingServer[Event]) error
	// Workspace enrollment is a client-owned pre-prompt bundle. These unary
	// controls carry only whole-bundle correlation; no backend selector exists.
	ConnectWorkspaceServices(context.Context, *WorkspaceEnrollmentConnectRequest) (*WorkspaceEnrollment, error)
	RetryWorkspaceEnrollment(context.Context, *WorkspaceEnrollmentControlRequest) (*WorkspaceEnrollment, error)
	CancelWorkspaceEnrollment(context.Context, *WorkspaceEnrollmentControlRequest) (*WorkspaceEnrollment, error)
	mustEmbedUnimplementedHarnessServiceServer()
}

